#!/usr/bin/env python3
"""Offline SIP identity boundary auditor (Boundary Profile 1).

Reads one JSON document on stdin, writes one JSON document on stdout.
Never opens a socket; standard library only.
"""

import sys
import json
import re
import hashlib
from collections import deque

MAX_INPUT_BYTES = 33554432
MAX_TOTAL_WIRE = 8388608
MAX_EVENTS = 10000
MAX_HEXLEN = 131072
MAX_T = 9007199254740991

ANON = "sip:anonymous@anonymous.invalid"

REQ_BODY_MAX = 65536
HDR_BLOCK_MAX = 32768
LINE_MAX = 8192
HDR_LINES_MAX = 256

_ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
_DIGITS = "0123456789"
_UNRESERVED = frozenset(_ALPHA + _DIGITS + "-_.!~*'()")
_TOKEN = frozenset(_ALPHA + _DIGITS + "-.!%*_+`'~")
_HEXCH = frozenset(_DIGITS + "abcdefABCDEF")
_TELSEP = frozenset("-.()")
_OWS = " \t"
_STOP = frozenset(';,<> \t"')

_TOKCLASS = r"[A-Za-z0-9\-\.!%*_+`'~]"
ID_RE = re.compile(r"[A-Za-z][A-Za-z0-9_-]{0,31}")
_LABEL = r"[A-Za-z0-9](?:[A-Za-z0-9\-]{0,61}[A-Za-z0-9])?"
HOST_RE = re.compile(_LABEL + r"(?:\." + _LABEL + r")+")
PORT_RE = re.compile(r"[0-9]{1,5}")
NAME_RE = re.compile(_TOKCLASS + r"+")
DN_RE = re.compile(_TOKCLASS + r"+(?:[ \t]+" + _TOKCLASS + r"+)*")
CL_RE = re.compile(r"[0-9]{1,10}")
CALLID_RE = re.compile(r"[A-Za-z0-9\-_.@]{1,64}")
HEXSTR_RE = re.compile(r"[0-9a-fA-F]*")
HDRBYTES_RE = re.compile(rb"[\x09\x20-\x7e]*")

COMPACT = {"f": "from", "t": "to", "i": "call-id", "l": "content-length"}
SINGLETONS = ("from", "to", "call-id", "content-length", "cseq")


class BadEnvelope(Exception):
    pass


class Reject(Exception):
    __slots__ = ("reason",)

    def __init__(self, reason):
        Exception.__init__(self, reason)
        self.reason = reason


# --------------------------------------------------------------------------
# URI canonicalization (section 2)
# --------------------------------------------------------------------------

def _decode_user(u):
    out = []
    i = 0
    n = len(u)
    while i < n:
        c = u[i]
        if c == "%":
            if i + 3 > n:
                return None
            h1 = u[i + 1]
            h2 = u[i + 2]
            if h1 not in _HEXCH or h2 not in _HEXCH:
                return None
            ch = chr(int(h1 + h2, 16))
            if ch not in _UNRESERVED:
                return None
            out.append(ch)
            i += 3
            continue
        if c in _UNRESERVED:
            out.append(c)
            i += 1
            continue
        return None
    return "".join(out)


def canon_sip(s):
    n = len(s)
    if n < 5:
        return None
    head = s[:5].lower()
    if head.startswith("sips:"):
        scheme = "sips"
        rest = s[5:]
    elif head.startswith("sip:"):
        scheme = "sip"
        rest = s[4:]
    else:
        return None
    at = rest.find("@")
    if at < 0:
        return None
    hostport = rest[at + 1:]
    if "@" in hostport:
        return None
    user = _decode_user(rest[:at])
    if user is None:
        return None
    ulen = len(user)
    if ulen < 1 or ulen > 64:
        return None
    colon = hostport.find(":")
    if colon < 0:
        host = hostport
        port = None
    else:
        host = hostport[:colon]
        pstr = hostport[colon + 1:]
        if not PORT_RE.fullmatch(pstr):
            return None
        pval = int(pstr)
        if pval < 1 or pval > 65535:
            return None
        port = pval
    hlen = len(host)
    if hlen < 1 or hlen > 253:
        return None
    if not HOST_RE.fullmatch(host):
        return None
    last = host[host.rfind(".") + 1:]
    if last[0] not in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz":
        return None
    out = scheme + ":" + user + "@" + host.lower()
    if port is not None:
        out += ":" + str(port)
    return out


def canon_tel(s):
    if len(s) < 5 or s[:4].lower() != "tel:":
        return None
    rest = s[4:]
    if not rest or rest[0] != "+":
        return None
    digits = []
    for c in rest[1:]:
        if c in _DIGITS and c not in _TELSEP:
            digits.append(c)
        elif c in _TELSEP:
            continue
        else:
            return None
    dn = len(digits)
    if dn < 3 or dn > 15:
        return None
    if digits[0] == "0":
        return None
    return "tel:+" + "".join(digits)


def canon_uri(s):
    """Return (canonical, is_tel) or (None, False) when s is not a valid URI."""
    head = s[:5].lower()
    if head.startswith("tel:"):
        r = canon_tel(s)
        return (r, True) if r is not None else (None, False)
    if head.startswith("sips:") or head.startswith("sip:"):
        r = canon_sip(s)
        return (r, False) if r is not None else (None, False)
    return (None, False)


# --------------------------------------------------------------------------
# Address / field grammar (section 3)
# --------------------------------------------------------------------------

def _skip_ows(s, i, n):
    while i < n and (s[i] == " " or s[i] == "\t"):
        i += 1
    return i


def _skip_quoted(s, i, n):
    # s[i] == '"' ; returns index just after the closing quote
    i += 1
    while i < n:
        c = s[i]
        if c == "\\":
            if i + 1 >= n:
                raise Reject("fields")
            d = s[i + 1]
            if d == "\t" or ("\x21" <= d <= "\x7e"):
                i += 2
                continue
            raise Reject("fields")
        if c == '"':
            return i + 1
        if c == " " or c == "\t" or ("\x21" <= c <= "\x7e"):
            i += 1
            continue
        raise Reject("fields")
    raise Reject("fields")


def _parse_bracket(s, i, n):
    j = s.find(">", i + 1)
    if j < 0:
        raise Reject("fields")
    uri, is_tel = canon_uri(s[i + 1:j])
    if uri is None:
        raise Reject("fields")
    return uri, is_tel, j + 1


def parse_address(s, i, n):
    """Parse one address starting at index i. Returns (uri, is_tel, next)."""
    i = _skip_ows(s, i, n)
    if i >= n:
        raise Reject("fields")
    c = s[i]
    if c == "<":
        return _parse_bracket(s, i, n)
    if c == '"':
        j = _skip_quoted(s, i, n)
        j = _skip_ows(s, j, n)
        if j >= n or s[j] != "<":
            raise Reject("fields")
        return _parse_bracket(s, j, n)
    k = s.find("<", i)
    if k >= 0:
        dn = s[i:k].rstrip(_OWS)
        if not dn or not DN_RE.fullmatch(dn):
            raise Reject("fields")
        return _parse_bracket(s, k, n)
    m = i
    while m < n and s[m] not in _STOP:
        m += 1
    uri, is_tel = canon_uri(s[i:m])
    if uri is None:
        raise Reject("fields")
    return uri, is_tel, m


def _split_commas(s):
    out = []
    cur = []
    depth = 0
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '"' and depth == 0:
            j = _skip_quoted(s, i, n)
            cur.append(s[i:j])
            i = j
            continue
        if c == "<":
            depth += 1
            cur.append(c)
            i += 1
            continue
        if c == ">":
            if depth > 0:
                depth -= 1
            cur.append(c)
            i += 1
            continue
        if c == "," and depth == 0:
            out.append("".join(cur))
            cur = []
            i += 1
            continue
        cur.append(c)
        i += 1
    out.append("".join(cur))
    return out


def parse_from(v):
    n = len(v)
    uri, is_tel, j = parse_address(v, 0, n)
    j = _skip_ows(v, j, n)
    if j >= n or v[j] != ";":
        raise Reject("fields")
    j = _skip_ows(v, j + 1, n)
    k = j
    while k < n and v[k] in _TOKEN:
        k += 1
    if v[j:k].lower() != "tag":
        raise Reject("fields")
    j = _skip_ows(v, k, n)
    if j >= n or v[j] != "=":
        raise Reject("fields")
    j = _skip_ows(v, j + 1, n)
    k = j
    while k < n and v[k] in _TOKEN:
        k += 1
    tag = v[j:k]
    tlen = len(tag)
    if tlen < 1 or tlen > 32 or k != n:
        raise Reject("fields")
    return uri, tag


def parse_to(v):
    n = len(v)
    uri, is_tel, j = parse_address(v, 0, n)
    if is_tel or j != n:
        raise Reject("fields")
    return uri


def parse_identity(rows):
    if rows is None:
        return None
    items = []
    for row in rows:
        for part in _split_commas(row):
            p = part.strip(_OWS)
            if not p:
                raise Reject("fields")
            uri, is_tel, j = parse_address(p, 0, len(p))
            if j != len(p):
                raise Reject("fields")
            items.append((uri, is_tel))
    cnt = len(items)
    if cnt < 1 or cnt > 2:
        raise Reject("fields")
    if cnt == 2:
        if items[0][1] == items[1][1]:
            raise Reject("fields")
        if items[0][1]:
            items = [items[1], items[0]]
    return [items[0][0]] if cnt == 1 else [items[0][0], items[1][0]]


def parse_privacy(rows):
    if rows is None:
        return "absent"
    seen = None
    for row in rows:
        for part in row.split(";"):
            it = part.strip(_OWS).lower()
            if it != "id" and it != "none":
                raise Reject("fields")
            if seen is None:
                seen = it
            elif seen != it:
                raise Reject("fields")
    if seen is None:
        raise Reject("fields")
    return seen


def parse_cseq(v, method):
    n = len(v)
    i = 0
    while i < n and v[i] in _DIGITS:
        i += 1
    if i < 1 or i > 10:
        raise Reject("fields")
    val = int(v[:i])
    if val < 1 or val > 2147483647:
        raise Reject("fields")
    j = _skip_ows(v, i, n)
    if j == i:
        raise Reject("fields")
    if v[j:] != method:
        raise Reject("fields")
    return val


# --------------------------------------------------------------------------
# Wire parsing (section 3)
# --------------------------------------------------------------------------

def parse_request(data):
    if len(data) > REQ_BODY_MAX:
        raise Reject("syntax")
    idx = data.find(b"\r\n\r\n")
    if idx < 0:
        raise Reject("syntax")
    hblock = data[:idx]
    body = data[idx + 4:]
    if len(hblock) > HDR_BLOCK_MAX:
        raise Reject("syntax")
    if not HDRBYTES_RE.fullmatch(hblock.replace(b"\r\n", b"")):
        raise Reject("syntax")
    lines = hblock.decode("ascii").split("\r\n")
    if len(lines) - 1 > HDR_LINES_MAX:
        raise Reject("syntax")
    for ln in lines:
        if len(ln) > LINE_MAX:
            raise Reject("syntax")

    start = lines[0].split(" ")
    if len(start) != 3:
        raise Reject("syntax")
    method = start[0]
    if method != "INVITE" and method != "MESSAGE":
        raise Reject("syntax")
    if start[2] != "SIP/2.0":
        raise Reject("syntax")
    target = canon_sip(start[1])
    if target is None:
        raise Reject("syntax")

    fields = []
    prev = None
    for ln in lines[1:]:
        c0 = ln[:1]
        if c0 == " " or c0 == "\t":
            if prev is None:
                raise Reject("syntax")
            prev[1] = prev[1].rstrip(_OWS) + " " + ln.lstrip(_OWS)
            continue
        colon = ln.find(":")
        if colon < 0:
            raise Reject("syntax")
        name = ln[:colon].rstrip(_OWS)
        if not name or not NAME_RE.fullmatch(name):
            raise Reject("syntax")
        name = name.lower()
        name = COMPACT.get(name, name)
        prev = [name, ln[colon + 1:]]
        fields.append(prev)

    groups = {}
    for name, value in fields:
        value = value.strip(_OWS)
        g = groups.get(name)
        if g is None:
            groups[name] = [value]
        else:
            g.append(value)

    for req in SINGLETONS:
        g = groups.get(req)
        if g is None or len(g) != 1:
            raise Reject("headers")

    cl = groups["content-length"][0]
    if not CL_RE.fullmatch(cl) or int(cl) != len(body):
        raise Reject("length")

    from_uri, tag = parse_from(groups["from"][0])
    to_uri = parse_to(groups["to"][0])
    if to_uri != target:
        raise Reject("fields")
    call_id = groups["call-id"][0]
    if not CALLID_RE.fullmatch(call_id):
        raise Reject("fields")
    cseq = parse_cseq(groups["cseq"][0], method)
    pai = parse_identity(groups.get("p-asserted-identity"))
    ppi = parse_identity(groups.get("p-preferred-identity"))
    privacy = parse_privacy(groups.get("privacy"))

    return {
        "method": method,
        "target": target,
        "body": body,
        "from_uri": from_uri,
        "tag": tag,
        "call_id": call_id,
        "cseq": cseq,
        "pai": pai,
        "ppi": ppi,
        "privacy": privacy,
    }


# --------------------------------------------------------------------------
# Envelope validation (section 1)
# --------------------------------------------------------------------------

def _fail(msg):
    raise BadEnvelope(msg)


def _int(x):
    if isinstance(x, bool) or not isinstance(x, int):
        _fail("integer required")
    return x


def _str(x):
    if not isinstance(x, str):
        _fail("string required")
    return x


def _list(x):
    if not isinstance(x, list):
        _fail("array required")
    return x


def _dict(x):
    if not isinstance(x, dict):
        _fail("object required")
    return x


def _exact(d, keys):
    if len(d) != len(keys):
        _fail("key set mismatch")
    for k in keys:
        if k not in d:
            _fail("missing key " + k)


def _pairs(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            _fail("duplicate key")
        d[k] = v
    return d


def _constant(name):
    _fail("bad constant " + name)


def validate(doc):
    d = _dict(doc)
    _exact(d, ("version", "config", "events"))
    if _int(d["version"]) != 1:
        _fail("version")
    cfg = _dict(d["config"])
    _exact(cfg, ("accounts", "peers", "ttl_ms", "capacity"))

    accounts = _list(cfg["accounts"])
    if len(accounts) > 256:
        _fail("too many accounts")
    acct_ids = set()
    alias_owner = {}
    defaults = {}
    for a in accounts:
        a = _dict(a)
        _exact(a, ("id", "default", "aliases"))
        aid = _str(a["id"])
        if not ID_RE.fullmatch(aid):
            _fail("account id")
        if aid in acct_ids:
            _fail("duplicate account id")
        acct_ids.add(aid)
        aliases = _list(a["aliases"])
        la = len(aliases)
        if la < 1 or la > 8:
            _fail("alias count")
        seen = set()
        for al in aliases:
            al = _str(al)
            c, _tel = canon_uri(al)
            if c is None or c != al:
                _fail("alias not canonical: " + al)
            if al == ANON:
                _fail("anonymous alias")
            if al in seen:
                _fail("duplicate alias")
            if al in alias_owner:
                _fail("alias owned twice")
            seen.add(al)
            alias_owner[al] = aid
        dflt = _str(a["default"])
        if dflt not in seen:
            _fail("default not an alias")
        defaults[aid] = dflt

    peers = _list(cfg["peers"])
    lp = len(peers)
    if lp < 1 or lp > 256:
        _fail("peer count")
    peer_mode = {}
    peer_accounts = {}
    for p in peers:
        p = _dict(p)
        _exact(p, ("id", "mode", "accounts"))
        pid = _str(p["id"])
        if not ID_RE.fullmatch(pid):
            _fail("peer id")
        if pid in peer_mode:
            _fail("duplicate peer id")
        mode = _str(p["mode"])
        if mode != "access" and mode != "relay":
            _fail("peer mode")
        accs = _list(p["accounts"])
        if mode == "access":
            if accs:
                _fail("access peer accounts")
            peer_accounts[pid] = frozenset()
        else:
            if len(accs) > 256:
                _fail("too many relay accounts")
            s = set()
            for x in accs:
                x = _str(x)
                if x not in acct_ids:
                    _fail("unknown relay account")
                if x in s:
                    _fail("duplicate relay account")
                s.add(x)
            peer_accounts[pid] = frozenset(s)
        peer_mode[pid] = mode

    ttl = _int(cfg["ttl_ms"])
    if ttl < 1 or ttl > 1000000:
        _fail("ttl_ms")
    cap = _int(cfg["capacity"])
    if cap < 1 or cap > 10000:
        _fail("capacity")

    evs = _list(d["events"])
    if len(evs) > MAX_EVENTS:
        _fail("too many events")
    norm = []
    total = 0
    prev_t = -1
    for e in evs:
        e = _dict(e)
        _exact(e, ("t", "peer", "auth", "egress", "wire_hex"))
        t = _int(e["t"])
        if t < 0 or t > MAX_T:
            _fail("t range")
        if t < prev_t:
            _fail("descending t")
        prev_t = t
        pid = _str(e["peer"])
        mode = peer_mode.get(pid)
        if mode is None:
            _fail("unknown peer")
        auth = e["auth"]
        if auth is not None:
            auth = _str(auth)
            if auth not in acct_ids:
                _fail("unknown account")
            if mode == "relay":
                _fail("relay auth must be null")
        eg = _str(e["egress"])
        if eg != "internal" and eg != "external":
            _fail("egress")
        hx = _str(e["wire_hex"])
        if len(hx) > MAX_HEXLEN:
            _fail("wire_hex length")
        total += len(hx) >> 1
        norm.append((t, pid, auth, eg, hx))
    if total > MAX_TOTAL_WIRE:
        _fail("wire byte budget")

    return {
        "alias_owner": alias_owner,
        "defaults": defaults,
        "peer_mode": peer_mode,
        "peer_accounts": peer_accounts,
        "ttl": ttl,
        "cap": cap,
        "events": norm,
    }


# --------------------------------------------------------------------------
# Policy (section 4) and ledger (section 5)
# --------------------------------------------------------------------------

def apply_policy(req, pid, auth, egress, ctx):
    mode = ctx["peer_mode"][pid]
    alias_owner = ctx["alias_owner"]
    pai = req["pai"]
    ppi = req["ppi"]
    privacy = req["privacy"]

    if mode == "access":
        if auth is None:
            raise Reject("auth")
        acct = auth
        if ppi is not None:
            for uri in ppi:
                if alias_owner.get(uri) != acct:
                    raise Reject("identity")
            asserted = ppi
            selected = ppi[0]
        else:
            selected = ctx["defaults"][acct]
            asserted = [selected]
    else:
        if ppi is not None or pai is None:
            raise Reject("identity")
        acct = None
        for uri in pai:
            owner = alias_owner.get(uri)
            if owner is None:
                raise Reject("identity")
            if acct is None:
                acct = owner
            elif owner != acct:
                raise Reject("identity")
        if acct not in ctx["peer_accounts"][pid]:
            raise Reject("identity")
        asserted = pai
        selected = pai[0]

    from_uri = req["from_uri"]
    if from_uri == ANON:
        if privacy != "id":
            raise Reject("identity")
    elif alias_owner.get(from_uri) != acct:
        raise Reject("identity")

    if privacy == "id":
        out_from = ANON
    else:
        out_from = selected
    if egress == "external" and privacy != "none":
        out_pai = []
    else:
        out_pai = list(asserted)

    req["account"] = acct
    req["selected"] = selected
    req["asserted"] = asserted
    req["out_from"] = out_from
    req["out_pai"] = out_pai
    return req


def record(index, first, req):
    return {
        "index": index,
        "decision": "accept" if first == index else "replay",
        "first": first,
        "account": req["account"],
        "identity": req["selected"],
        "from": req["out_from"],
        "pai": req["out_pai"],
        "method": req["method"],
        "target": req["target"],
        "call_id": req["call_id"],
        "cseq": req["cseq"],
        "tag": req["tag"],
        "privacy": req["privacy"],
        "body_sha256": hashlib.sha256(req["body"]).hexdigest(),
    }


def run(ctx):
    ttl = ctx["ttl"]
    cap = ctx["cap"]
    ledger = {}
    order = deque()
    results = []
    nacc = 0
    nrep = 0
    nrej = 0

    for index, (t, pid, auth, egress, hx) in enumerate(ctx["events"]):
        while order:
            k = order[0]
            ent = ledger.get(k)
            if ent is None:
                order.popleft()
                continue
            if t >= ent[2] + ttl:
                del ledger[k]
                order.popleft()
            else:
                break

        if (len(hx) & 1) or not HEXSTR_RE.fullmatch(hx):
            results.append({"index": index, "decision": "reject", "reason": "hex"})
            nrej += 1
            continue
        try:
            data = bytes.fromhex(hx)
            req = parse_request(data)
            req = apply_policy(req, pid, auth, egress, ctx)
        except Reject as exc:
            results.append({"index": index, "decision": "reject", "reason": exc.reason})
            nrej += 1
            continue

        key = (pid, req["call_id"], req["cseq"], req["method"])
        commitment = (
            req["account"],
            req["selected"],
            tuple(req["asserted"]),
            req["from_uri"],
            req["tag"],
            req["target"],
            req["privacy"],
            egress,
            req["body"],
        )
        ent = ledger.get(key)
        if ent is None:
            if len(ledger) >= cap:
                old = order.popleft()
                del ledger[old]
            ledger[key] = (commitment, index, t)
            order.append(key)
            results.append(record(index, index, req))
            nacc += 1
        elif ent[0] == commitment:
            results.append(record(index, ent[1], req))
            nrep += 1
        else:
            results.append({"index": index, "decision": "reject", "reason": "conflict"})
            nrej += 1

    return {
        "results": results,
        "accepted": nacc,
        "replayed": nrep,
        "rejected": nrej,
